import json
tools={}
with open('.agent/runs/mcp-connector-slice-13/62ea2e3e3c694c66b0dbc613009be5aa-remediate-events.jsonl') as f:
    for line in f:
        line=line.strip()
        if not line: continue
        try: o=json.loads(line)
        except: continue
        if o.get('type')=='tool_use':
            part=o.get('part',{})
            tool=part.get('tool','?')
            inp=part.get('state',{}).get('input',{})
            desc=''
            for k in ('command','path','url','query','code','oldString','newString'):
                if k in inp:
                    desc=str(inp[k])[:100]; break
            tools[tool]=tools.get(tool,0)+1
            print(f'{tool} | {desc}')
print()
print('=== tool counts ===')
for t,c in sorted(tools.items()):
    print(f'  {t}: {c}')
""}

