import json
path=".agent/runs/mcp-connector-slice-13/62ea2e3e3c694c66b0dbc613009be5aa-remediate-events.jsonl"
for line in open(path):
    line=line.strip()
    if not line: continue
    try: obj=json.loads(line)
    except: continue
    # find tool calls
    def walk(o):
        if isinstance(o,dict):
            if o.get("tool") in ("edit","write") or (isinstance(o.get("name"),str) and o["name"] in ("edit","write")):
                yield o
            for v in o.values(): yield from walk(v)
        elif isinstance(o,list):
            for v in o: yield from walk(v)
    for t in walk(obj):
        name=t.get("tool") or t.get("name")
        inp=t.get("input") or t.get("arguments") or t.get("params") or {}
        if isinstance(inp,str):
            try: inp=json.loads(inp)
            except: pass
        p=inp.get("path") or inp.get("file_path") or ""
        old=inp.get("oldString") or inp.get("old_string") or ""
        new=inp.get("newString") or inp.get("new_string") or ""
        content=inp.get("content") or ""
        print("TOOL:",name,"PATH:",p)
        if old: print("  OLD:",repr(old[:200]))
        if new: print("  NEW:",repr(new[:200]))
        if content: print("  CONTENT(len):",len(content),repr(content[:120]))
        print()
'

